insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'The nature of business activity and business data', 'A shop''s sales rose from £40,000 last year to £50,000 this year. What is the percentage change in sales?', '20% increase', '25% increase', '125% increase', '10% increase', 'B', 'Percentage change = change ÷ original × 100 = (50,000 − 40,000) ÷ 40,000 × 100 = 25%. Dividing by the new figure (50,000) wrongly gives 20%.', 'foundation', 'calculation', 'AO2'),
  (2, 'The nature of business activity and business data', 'Total sales in a local market are £2 million. One business has sales of £300,000. What is its market share?', '1.5%', '6.7%', '30%', '15%', 'D', 'Market share = business sales ÷ total market sales × 100 = 300,000 ÷ 2,000,000 × 100 = 15%.', 'foundation', 'calculation', 'AO2'),
  (3, 'The nature of business activity and business data', 'A business''s profit fell from £80,000 to £60,000. What is the percentage change in profit?', 'A rise of 25%', 'A fall of 25%', 'A fall of 20%', 'A fall of 33.3%', 'B', 'Change = −20,000. −20,000 ÷ 80,000 × 100 = −25%. Always divide by the original (old) figure.', 'higher', 'calculation', 'AO2'),
  (4, 'The nature of business activity and business data', 'Which of these is an example of qualitative data?', 'Monthly sales figures', 'The number of website visits each week', 'Comments from customers in a focus group', 'Market share percentages', 'C', 'Qualitative data is about opinions, feelings and reasons. Quantitative data is numerical, such as sales or market share.', 'foundation', 'recall', 'AO1'),
  (5, 'The nature of business activity and business data', 'A café''s sales on four days were £200, £300, £250 and £450. What was its mean (average) daily sales?', '£1,200', '£300', '£275', '£250', 'B', 'Mean = total ÷ number of days = 1,200 ÷ 4 = £300. £1,200 is the total, not the average.', 'foundation', 'calculation', 'AO2'),
  (6, 'The nature of business activity and business data', 'What does it mean to say that business activity is interdependent?', 'Each department works on its own, separately from the rest', 'Only the owners are involved in making decisions', 'The business does not rely on any other businesses', 'A decision in one department affects the others', 'D', 'For example, a marketing campaign that raises demand means operations must produce more and finance must fund it.', 'foundation', 'recall', 'AO1'),
  (7, 'Providing goods and services', 'Which of these is a producer good?', 'A haircut at a salon', 'A delivery van bought by a bakery', 'A chocolate bar bought by a shopper', 'A games console bought as a present', 'B', 'Producer goods are bought by businesses to help them produce other goods and services. The others are bought by consumers for their own use.', 'foundation', 'recall', 'AO1'),
  (8, 'Providing goods and services', 'Which of these is a non-durable good?', 'A pint of fresh milk', 'A second-hand family car', 'A new washing machine', 'A laptop for schoolwork', 'A', 'Non-durable goods are used up quickly or in one go. Durable goods last a long time and are used again and again.', 'foundation', 'recall', 'AO1'),
  (9, 'Providing goods and services', 'Which of these organisations is in the public sector?', 'A self-employed plumber', 'A national supermarket chain', 'A private furniture company', 'A hospital run by the NHS', 'D', 'The public sector is owned and run by the government and funded mainly by taxes. The others are private sector businesses.', 'foundation', 'recall', 'AO1'),
  (10, 'Business enterprise and entrepreneurs', 'Which characteristic is an entrepreneur most likely to have?', 'Disliking new ideas', 'Preferring a guaranteed salary', 'Avoiding making decisions', 'Being willing to take risks', 'D', 'Entrepreneurs risk their own money and time to start a business. They also show initiative, innovation and determination.', 'foundation', 'recall', 'AO1'),
  (11, 'Business enterprise and entrepreneurs', 'What is the main motive of a social enterprise?', 'To avoid paying any tax', 'To provide public services paid for by taxes', 'To pay the highest possible dividends to shareholders', 'To help a social or community cause', 'D', 'A social enterprise trades like a business but uses its profits mainly to benefit society or the community.', 'foundation', 'recall', 'AO1'),
  (12, 'Business enterprise and entrepreneurs', 'Which of these is a non-financial reward of business enterprise?', 'Receiving dividends on the shares owned', 'Making a profit at the end of the year', 'Satisfaction from building something', 'Drawing a regular salary from the business', 'C', 'Non-financial rewards include satisfaction, independence and good customer feedback. The other options are all financial rewards.', 'foundation', 'recall', 'AO1'),
  (13, 'Business planning', 'Why would a bank want to see a business plan before giving a start-up a loan?', 'To find out the names of the business''s competitors'' customers', 'Because a business plan is a legal requirement for all businesses', 'To judge whether the business is likely to be able to repay the loan', 'To decide what price the business should charge', 'C', 'The plan shows the bank the business idea, the market and the financial forecasts, so it can judge the risk of lending.', 'foundation', 'applied', 'AO2'),
  (14, 'Business planning', 'In which section of a business plan would a cash-flow forecast usually appear?', 'Human resources', 'Marketing', 'Production operations', 'Financial', 'D', 'The financial section includes forecasts of cash-flow, sales, costs and profit, and how much finance is needed.', 'foundation', 'recall', 'AO1'),
  (15, 'Business aims and objectives', 'Which of these is a SMART objective?', 'Raise sales by 10% within 12 months', 'Improve our customer service as soon as we can', 'Make as much profit as we possibly can', 'Become much more popular with all our customers', 'A', 'SMART objectives are Specific, Measurable, Agreed, Realistic and Timed. Only this one has a measurable target and a time limit.', 'foundation', 'applied', 'AO2'),
  (16, 'Business aims and objectives', 'A café has just opened in a busy area with many competitors. What is its most likely main aim for its first year?', 'Growth overseas', 'Survival', 'Market leadership', 'Profit maximisation', 'B', 'Many new businesses fail in their first year, so they usually focus on surviving before aiming for growth or high profit.', 'foundation', 'applied', 'AO2'),
  (17, 'Business aims and objectives', 'What is the difference between a business aim and a business objective?', 'An aim is set by employees; an objective is set by customers', 'An aim is short term; an objective is always long term', 'An aim is a broad goal; objectives are measurable steps to it', 'An aim is always about profit; an objective never is', 'C', 'Objectives break an aim down into measurable steps, which also let the business measure its performance.', 'foundation', 'recall', 'AO1'),
  (18, 'Stakeholders', 'Which of these is an internal stakeholder?', 'Employees', 'Customers', 'Suppliers', 'The local community', 'A', 'Internal stakeholders work within the business: owners, managers and employees. The others are external stakeholders.', 'foundation', 'recall', 'AO1'),
  (19, 'Stakeholders', 'A business cuts wages so that it can increase profits. Which two stakeholder groups'' interests conflict most clearly?', 'Owners and employees', 'Suppliers and the government', 'Customers and suppliers', 'The government and the local community', 'A', 'Owners gain from higher profit, but employees lose from lower wages. Stakeholder objectives often conflict like this.', 'foundation', 'applied', 'AO2'),
  (20, 'Stakeholders', 'A supermarket plans to open a 24-hour store next to a housing estate. Which stakeholder group is most likely to object?', 'People looking for jobs', 'The supermarket''s shareholders', 'People living near the store', 'The supermarket''s suppliers', 'C', 'Residents may suffer from noise, traffic and lights at night. Shareholders, suppliers and job seekers are likely to benefit.', 'foundation', 'applied', 'AO2'),
  (21, 'Business ownership', 'What does unlimited liability mean?', 'The business is never required to pay any tax on its profits', 'Owners may have to sell personal belongings to pay business debts', 'The business is allowed to borrow as much money as it likes', 'Owners can only lose the money they put into the business', 'B', 'Sole traders and partnerships have unlimited liability. Shareholders in limited companies can only lose what they invested.', 'foundation', 'recall', 'AO1'),
  (22, 'Business ownership', 'What is the main difference between a private limited company (Ltd) and a public limited company (plc)?', 'A plc is owned and run by the government', 'Only a plc can sell shares on the stock exchange', 'A private limited company cannot employ any staff', 'Only a private limited company has limited liability', 'B', 'Both have limited liability. A plc can raise large amounts by selling shares to anyone; Ltd shares are sold privately, often to family and friends.', 'foundation', 'recall', 'AO1'),
  (23, 'Business ownership', 'What is a key feature of a co-operative?', 'Its shares are traded on the stock exchange', 'It is run by the government', 'It is owned by one person with unlimited liability', 'It is owned by its members, who share in the profits', 'D', 'In a co-operative, members (such as customers or workers) own the business, have a say in decisions and share the profits.', 'foundation', 'recall', 'AO1'),
  (24, 'Business ownership', 'Two friends want to start a small web design business. They want to share decisions, keep control themselves and protect their personal savings if it fails. Which type of ownership is most suitable?', 'Private limited company', 'Public limited company', 'Sole trader', 'Partnership', 'A', 'A private limited company gives limited liability while letting the friends keep control. A partnership has unlimited liability, and a plc is for large businesses selling shares to the public.', 'higher', 'applied', 'AO3'),
  (25, 'Business growth', 'A brewery buys a chain of pubs that sell its beer. What type of growth is this?', 'Organic growth', 'Horizontal integration', 'Backward vertical integration', 'Forward vertical integration', 'D', 'The brewery has joined with a business at a later stage of its own supply chain (closer to the customer), so it is forward vertical integration.', 'higher', 'applied', 'AO2'),
  (26, 'Business growth', 'Which of these is an example of internal (organic) growth?', 'Opening new branches using retained profit', 'Taking over one of its main suppliers', 'Buying a rival business in another town', 'Merging with a competitor to form one business', 'A', 'Organic growth comes from within the business, such as selling more, opening new outlets or launching new products. Mergers and takeovers are external growth.', 'foundation', 'applied', 'AO2'),
  (27, 'Business growth', 'A large supermarket pays a lower price per tin of beans than a corner shop because it buys millions of tins. Which internal economy of scale is this?', 'Purchasing', 'Financial', 'Administrative', 'Technical', 'A', 'Buying in bulk lowers the cost per unit. This is a purchasing economy of scale.', 'foundation', 'applied', 'AO2'),
  (28, 'Business growth', 'What is an advantage for a franchisee of opening a franchise rather than starting a new business from scratch?', 'It has no start-up costs to pay at the beginning', 'It keeps all of its profits with no fees to pay', 'It has complete freedom over the products it sells', 'It trades under a known brand, so risk is lower', 'D', 'Franchisees benefit from a known brand and support from the franchisor, but they pay fees or royalties and must follow the franchisor''s rules.', 'foundation', 'recall', 'AO1'),
  (29, 'Business location and site', 'A bakery chooses a site on a busy high street. Which siting factor has it most likely focused on?', 'Cheap rent', 'Being far from competitors', 'Access to raw materials', 'High footfall', 'D', 'Footfall is the number of people passing a site. A busy high street brings more potential customers but usually higher rent.', 'foundation', 'applied', 'AO2'),
  (30, 'Business location and site', 'A steel manufacturer uses huge amounts of heavy raw materials. Where is it most likely to locate?', 'Right next to its competitors', 'Close to its raw materials', 'In a busy city-centre street', 'Wherever the owner lives', 'B', 'Heavy, bulky materials are expensive to transport, so being close to them, with good infrastructure, keeps costs down.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Activity') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

