from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Activity') and z.title = 'Quiz ' || ((o.i % 2) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Activity');

