insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Technological influence, e-commerce and business software', 'What is m-commerce?', 'Selling goods through a printed catalogue', 'Trading goods and services between countries', 'Paying in a shop with a contactless debit card', 'Buying goods and services on a smartphone', 'D', 'E-commerce is buying online via the internet; m-commerce is the part of it done on mobile devices.', 'foundation', 'recall', 'AO1'),
  (2, 'Technological influence, e-commerce and business software', 'A business wants to calculate its monthly costs and test different sales forecasts. Which type of software is most suitable?', 'Presentation software', 'A database', 'A spreadsheet', 'A word processor', 'C', 'Spreadsheets are used to make calculations, and formulas update automatically when figures change.', 'foundation', 'applied', 'AO2'),
  (3, 'Technological influence, e-commerce and business software', 'What is a database mainly used for in a business?', 'Storing records that can be searched and sorted', 'Holding live video meetings with other offices', 'Designing new products on screen before they are made', 'Writing and formatting letters and reports', 'A', 'Databases store records. Word processors are for documents, CAD is for design and video conferencing is for meetings.', 'foundation', 'recall', 'AO1'),
  (4, 'Technological influence, e-commerce and business software', 'What is computer aided manufacture (CAM)?', 'Using the internet to sell products to customers', 'Using computers to design products on screen', 'Making products with computer-controlled machines', 'Using spreadsheets to plan the costs of production', 'C', 'CAD (computer aided design) is used to design products; CAM uses computer-controlled machinery to make them, often more accurately and quickly.', 'foundation', 'recall', 'AO1'),
  (5, 'Technological influence, e-commerce and business software', 'Which is a disadvantage to a small business of introducing new technology?', 'It can reduce mistakes in calculations', 'The high cost of buying and installing it', 'It allows faster communication with customers', 'It lets the business reach customers online', 'B', 'Technology can be expensive, especially for small businesses. Other drawbacks include dependency on technology and security breaches.', 'foundation', 'recall', 'AO1'),
  (6, 'Technological influence, e-commerce and business software', 'A high street clothes shop is losing sales as more customers buy clothes online. Which response is most likely to help it?', 'Raise its prices to make up for the lost sales', 'Cut its opening hours to reduce its costs', 'Start selling online through its own website', 'Stop all of its advertising to save money', 'C', 'In a dynamic market, businesses need to use new technology to sell their products. Selling online lets it reach the customers it is losing.', 'higher', 'applied', 'AO3'),
  (7, 'Ethical influence', 'What does Fairtrade aim to do?', 'Make sure products are always sold at the lowest possible price', 'Stop UK businesses from importing goods from other countries', 'Make sure that all food products sold are grown organically', 'Give producers in developing countries a fair minimum price', 'D', 'Fairtrade gives farmers a fair price and better working conditions. It is one of the ethical issues in the specification.', 'foundation', 'recall', 'AO1'),
  (8, 'Ethical influence', 'Why might adopting ethical policies reduce a business''s profit in the short term?', 'Ethical businesses are not allowed to advertise', 'Customers always refuse to buy ethical products', 'Ethical businesses must pay extra tax on profits', 'Ethical materials and fair wages often cost more', 'D', 'Ethics can conflict with profit because ethical choices often raise costs, although they may attract more customers in the long run.', 'foundation', 'applied', 'AO2'),
  (9, 'Ethical influence', 'Which is a likely benefit for a business of adopting ethical policies?', 'It will no longer face any competition in its market', 'It may attract customers who care how products are made', 'Its costs will always fall, whatever policies it chooses', 'It will no longer need to follow consumer or employment law', 'B', 'Benefits include attracting consumers, more stable relationships with suppliers and better employee motivation.', 'foundation', 'recall', 'AO1'),
  (10, 'Environmental influence', 'In business, what is meant by sustainability?', 'Only selling products that are built to last for years', 'Avoiding using up natural resources needed in the future', 'Keeping prices the same for a long period of time', 'Making a profit every year for as long as possible', 'B', 'Sustainable businesses try to avoid depleting natural resources, for example through renewable energy and recycling.', 'foundation', 'recall', 'AO1'),
  (11, 'Environmental influence', 'Which of these is an environmental cost of business activity?', 'Pollution from a factory chimney', 'Paying staff higher wages', 'The cost of training new staff', 'Interest paid on a bank loan', 'A', 'Environmental costs include pollution, climate change, congestion and the use of finite resources.', 'foundation', 'recall', 'AO1'),
  (12, 'Environmental influence', 'A business switches to biodegradable packaging. What is a likely disadvantage?', 'It will create a lot more waste than before', 'Customers will be less likely to buy from it', 'Higher costs, which may raise prices', 'It will have to stop all of its recycling', 'C', 'Environmentally friendly policies can attract customers and motivate staff, but they often increase costs.', 'foundation', 'applied', 'AO2'),
  (13, 'Economic influence', 'Interest rates rise. How is this most likely to affect a business with a large bank loan?', 'It no longer has to repay the loan', 'Its loan repayments fall, which increases its profit', 'Its sales will rise immediately', 'Its loan repayments increase, which reduces its profit', 'D', 'Higher interest rates make borrowing more expensive. They may also reduce consumer spending as people''s loans and mortgages cost more.', 'foundation', 'applied', 'AO2'),
  (14, 'Economic influence', 'Unemployment in an area rises sharply. How is this most likely to affect a local luxury car dealer?', 'Sales rise because people have more free time', 'Sales fall as many people have less income', 'It is not affected, as cars are always needed', 'Costs rise because it must pay higher wages', 'B', 'When unemployment rises, consumer incomes fall and people cut back on expensive purchases such as luxury cars.', 'higher', 'applied', 'AO3'),
  (15, 'Economic influence', 'What is VAT?', 'A tax paid only by exporters', 'A direct tax on income', 'An indirect tax on spending', 'A tax on company profits', 'C', 'VAT is added to the price of many goods and services. Income tax is a direct tax on income; corporation tax is on company profits.', 'foundation', 'recall', 'AO1'),
  (16, 'Economic influence', 'What is corporation tax charged on?', 'The wages of employees', 'The price of goods in shops', 'Imports into the UK', 'The profits of companies', 'D', 'Corporation tax is a direct tax on company profits. Income tax is paid on wages and VAT on spending.', 'foundation', 'recall', 'AO1'),
  (17, 'Economic influence', 'Consumer incomes in the UK rise. Which business is most likely to see the biggest increase in sales?', 'A business that repairs old shoes', 'A shop selling second-hand clothes', 'A shop selling basic food at low prices', 'A company selling luxury holidays', 'D', 'When incomes rise, people spend more on luxuries and less on cheap alternatives such as repairs and second-hand goods.', 'foundation', 'applied', 'AO3'),
  (18, 'Globalisation', 'What is an export?', 'A product made and sold within the UK', 'A UK product sold to buyers abroad', 'A product a UK firm buys from abroad', 'A tax on goods coming into the UK', 'B', 'International trade involves exports (selling abroad) and imports (buying from abroad).', 'foundation', 'recall', 'AO1'),
  (19, 'Globalisation', 'Which is a reason why a business might want to become a multinational company?', 'To reduce the size of its market', 'To produce where costs are lower', 'To avoid having any competitors', 'To stop using its brand abroad', 'B', 'Reasons include cheaper production costs, larger market share, economies of scale, avoiding trade barriers and government grants.', 'foundation', 'recall', 'AO1'),
  (20, 'Globalisation', 'A foreign multinational opens a factory in the UK. Which is a possible negative impact?', 'Profits may go to its home country', 'Consumers have more choice of products', 'It introduces new technology to the UK', 'It creates new jobs for local people', 'A', 'The other options are positive impacts. Negatives include profits leaving the UK, environmental damage and deskilled jobs.', 'higher', 'applied', 'AO2'),
  (21, 'Globalisation', 'Which is a disadvantage for a UK business of selling its products abroad?', 'Language barriers and currency changes', 'Spreading risk across several countries', 'Access to new markets with more customers', 'Higher sales and profits from extra demand', 'A', 'International trade brings new markets and growth, but also language, supply chain and currency issues, and different local taxes and laws.', 'foundation', 'recall', 'AO1'),
  (22, 'Globalisation', 'What is the European single market?', 'A market in which every product must be sold at the same price', 'A single shop that sells goods from every country in Europe', 'An area where goods, services, people and money move freely', 'A trade agreement that bans all imports from outside Europe', 'C', 'In the single market, businesses trade without tariffs and follow shared regulations.', 'foundation', 'recall', 'AO1'),
  (23, 'Legislation', 'A business pays a 22-year-old worker less than the legal minimum hourly rate. Which area of law is it breaking?', 'Intellectual property law', 'Trade descriptions law', 'Consumer law', 'Employment law', 'D', 'Employment law gives employees rights to the minimum wage, a contract, safe working conditions and protection from discrimination and unfair dismissal.', 'foundation', 'applied', 'AO2'),
  (24, 'Legislation', 'Under consumer law, goods sold to customers must be…', 'made in the UK from British materials', 'of satisfactory quality and as described', 'the cheapest version available on the market', 'available to buy in every shop in the area', 'B', 'Consumer law protects customers against unsatisfactory quality, misleading advertising and inaccurate descriptions.', 'foundation', 'recall', 'AO1'),
  (25, 'Legislation', 'An inventor creates a new type of engine. What should they apply for to stop others copying it?', 'A patent', 'A copyright', 'A franchise', 'A trademark', 'A', 'Patents protect inventions. Copyright protects written and artistic works, and trademarks protect logos and brand names.', 'foundation', 'applied', 'AO2'),
  (26, 'Legislation', 'A business wants to stop other firms using its logo. Which type of intellectual property protection should it use?', 'A trademark', 'A patent', 'A contract of employment', 'A copyright', 'A', 'A trademark protects a brand name, logo or slogan.', 'foundation', 'applied', 'AO2'),
  (27, 'Legislation', 'New health and safety laws require factories to fit extra machine guards. How is this most likely to affect a factory?', 'It is allowed to pay its workers less', 'Its sales rise straight away as a result', 'It no longer needs to train any of its staff', 'Its costs rise, which may reduce profit', 'D', 'Legislation affects costs, profits and production. Meeting new laws often means spending on equipment and training.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Influences on Business') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Influences on Business'), 'Quiz 1', 1, 0, 168);
insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Influences on Business'), 'Quiz 2', 2, 0, 168);
