insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Business'), 'Business Operations', 'B3', 'Components 1 and 2', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations'), 'Methods of production', 'B3.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations'), 'Quality', 'B3.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations'), 'Supply chain', 'B3.3', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations'), 'Sales process and customer service', 'B3.4', 4);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Methods of production', 'What is job production?', 'Making a set number of identical products, then switching to another product', 'Making large quantities of identical products continuously', 'Buying finished products and reselling them', 'Making a single, one-off product to a customer''s own requirements', 'D', 'Examples include wedding dresses and made-to-measure kitchens. Batch makes groups of identical items; flow makes products continuously.', 'foundation', 'recall', 'AO1'),
  (2, 'Methods of production', 'A bakery makes 200 white loaves, then 200 brown loaves, then 200 rolls. Which method of production is this?', 'Just in time', 'Flow production', 'Job production', 'Batch production', 'D', 'Batch production makes a group of identical products before changing to a different product.', 'foundation', 'applied', 'AO2'),
  (3, 'Methods of production', 'What is the main advantage of flow (mass) production?', 'A low cost per unit because huge quantities are made', 'The machinery is cheap to set up', 'Every product can be made to the customer''s own design', 'Workers find the work very varied', 'A', 'Flow production spreads costs over very large output. Its drawbacks include high set-up costs and repetitive work.', 'foundation', 'recall', 'AO1'),
  (4, 'Methods of production', 'What is a disadvantage of flow production for employees?', 'The work is often repetitive and boring', 'They have to be highly skilled craftspeople', 'They must design each product individually', 'They are paid more than in job production', 'A', 'On a production line each worker may do the same task again and again, which can be boring.', 'foundation', 'recall', 'AO1'),
  (5, 'Methods of production', 'A company builds kitchens to fit each customer''s measurements. Which method of production is most appropriate?', 'Job production', 'Flow production', 'Batch production', 'Mass production', 'A', 'Each kitchen is unique and made to order, so job production is the most suitable method.', 'foundation', 'applied', 'AO2'),
  (6, 'Methods of production', 'A furniture maker switches from job production to batch production. What is the most likely effect?', 'It will need far more highly skilled workers', 'Higher unit costs, but much more customisation', 'Each item can now be made to an exact design', 'Lower unit costs, but less customisation', 'D', 'Making identical items in batches spreads costs over more units, but customers can no longer choose an individual design.', 'higher', 'applied', 'AO3'),
  (7, 'Quality', 'What is quality control?', 'Setting the price of a high-quality product', 'Inspecting finished products for faults', 'Checking quality at every stage to prevent faults', 'Training workers in how to sell products', 'B', 'Quality control inspects products to find faults. Quality assurance builds checks into every stage to prevent them.', 'foundation', 'recall', 'AO1'),
  (8, 'Quality', 'What is quality assurance?', 'Offering customers a full refund if they are unhappy', 'Inspecting only the finished products at the very end', 'Checking quality at every stage to prevent faults', 'Buying the cheapest raw materials that are available', 'C', 'With quality assurance, every worker is responsible for quality throughout production.', 'foundation', 'recall', 'AO1'),
  (9, 'Quality', 'Why is quality important to a business?', 'It always allows the business to pay lower wages', 'It reduces returns and waste, which lowers costs', 'It means the business does not need any customers', 'It removes the need for market research', 'B', 'Good quality satisfies customer expectations, increases sales and reduces costs and waste.', 'foundation', 'recall', 'AO1'),
  (10, 'Quality', 'A restaurant gets complaints about rude and slow service. Which action is most likely to improve the quality of its service?', 'Buying cheaper ingredients for meals', 'Training staff in customer service', 'Reducing the number of waiting staff', 'Raising the prices on its menu', 'B', 'Employing the right people and training them are key ways a business achieves quality, especially in services.', 'foundation', 'applied', 'AO2'),
  (11, 'Quality', 'Why might quality assurance lower a business''s costs compared with relying only on quality control?', 'It removes the need to buy any raw materials at all', 'It allows the business to charge lower prices to customers', 'It means that no workers ever need to be trained', 'Faults are prevented early, so less output is wasted', 'D', 'Quality control finds faults after products are made, when the materials and labour are already spent. Preventing faults earlier cuts waste.', 'higher', 'applied', 'AO3'),
  (12, 'Supply chain', 'In the supply chain, what is procurement?', 'Advertising the products to customers', 'Transporting finished goods to customers', 'Finding suppliers and buying supplies', 'Storing stock safely in a warehouse', 'C', 'Procurement is sourcing and purchasing. Logistics covers transport, storage and distribution.', 'foundation', 'recall', 'AO1'),
  (13, 'Supply chain', 'Which of these is part of logistics?', 'Distributing products to customers', 'Setting the selling price of products', 'Choosing which suppliers to buy from', 'Interviewing and appointing new staff', 'A', 'Logistics includes transportation, storage (warehousing) and distribution to the end customer.', 'foundation', 'recall', 'AO1'),
  (14, 'Supply chain', 'What is just in time (JIT) stock control?', 'Stock arrives just as it is needed', 'Large amounts of stock are kept for emergencies', 'Stock is only counted at the end of the year', 'All stock is ordered just once a year', 'A', 'JIT reduces storage costs and waste, but depends on reliable suppliers.', 'foundation', 'recall', 'AO1'),
  (15, 'Supply chain', 'What is the main risk for a car factory that uses just in time stock control?', 'It cannot use computerised stock control', 'If a supplier delivers late, production may have to stop', 'It has to pay very high warehouse costs', 'Its stock may go out of date because it holds so much', 'B', 'JIT holds almost no buffer stock, so any delay in the supply chain can halt production.', 'higher', 'applied', 'AO3'),
  (16, 'Supply chain', 'A café switches to a cheaper coffee supplier overseas. What is a likely risk?', 'It will need to open more cafés to survive', 'Deliveries may be less reliable', 'It will have to raise all of its prices', 'Its costs of buying coffee will rise', 'B', 'Supply decisions affect cost, quality and reliability. Cheaper supplies from far away can be harder to get on time.', 'higher', 'applied', 'AO2'),
  (17, 'Sales process and customer service', 'In the sales process, what happens after the sale has been closed?', 'Preparing good product knowledge', 'Following up with after-sales service', 'Finding out what the customer needs', 'Identifying new sales opportunities', 'B', 'The stages run: prepare, identify opportunities, understand needs, inform of features and benefits, close the sale, then follow up.', 'foundation', 'recall', 'AO1'),
  (18, 'Sales process and customer service', 'What is a benefit to a business of good customer service?', 'Lower wages for staff', 'Customers will accept poor-quality products', 'No need for any promotion', 'More customer loyalty and repeat business', 'D', 'Good service increases loyalty and spending, improves reputation and attracts new customers.', 'foundation', 'recall', 'AO1'),
  (19, 'Sales process and customer service', 'Which of these is a feature of good customer service?', 'Rushing customers so more can be served', 'Asking for feedback and responding to it', 'Avoiding contact after the sale', 'Only greeting regular customers', 'B', 'Good service includes greeting and interacting with customers, identifying their needs, and encouraging and responding to feedback.', 'foundation', 'recall', 'AO1'),
  (20, 'Sales process and customer service', 'How can an online retailer provide good customer service?', 'Hide its contact details on the website to cut costs', 'Remove product descriptions so the site loads faster', 'Offer live chat and clear returns information', 'Never reply to any reviews that customers post', 'C', 'Online businesses adapt good service for their websites, for example through quick responses, clear information and easy returns.', 'foundation', 'applied', 'AO2'),
  (21, 'Sales process and customer service', 'How is the sales process for a new car likely to differ from selling a magazine in a shop?', 'There is no need to close the sale with the customer', 'More time is spent explaining features and following up', 'The customer never needs to ask the salesperson anything', 'The sale must always be made online rather than in person', 'B', 'High-value sales need more product knowledge, time with the customer and after-sales service.', 'higher', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

