select z.id, o.id, (o.i / 2)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations') and z.title = 'Quiz ' || ((o.i % 2) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Business Operations');

insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Business'), 'Finance', 'B4', 'Components 1 and 2', 4);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Finance'), 'Sources of finance', 'B4.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Finance'), 'Revenue, costs and profit', 'B4.2', 2);
