insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Finance'), 'Cash-flow', 'B4.6', 6);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Sources of finance', 'Which of these is an internal source of finance?', 'A bank overdraft', 'A bank loan', 'Retained profit', 'Trade credit', 'C', 'Internal sources come from within the business: owner''s capital, retained profit and selling assets.', 'foundation', 'recall', 'AO1'),
  (2, 'Sources of finance', 'What is trade credit?', 'A bank loan that is repaid with interest', 'Money invested in the business by its owner', 'Buying from suppliers and paying later', 'Selling shares in the business to the public', 'C', 'Trade credit is usually 30 to 90 days. It helps cash-flow because the business can sell the goods before paying for them.', 'foundation', 'recall', 'AO1'),
  (3, 'Sources of finance', 'A business has a short-term cash shortage for a few weeks. Which source of finance is most suitable?', 'A share issue', 'Selling the business''s factory', 'A bank overdraft', 'A 10-year bank loan', 'C', 'An overdraft is flexible and meant for short-term needs. The others are for long-term finance.', 'foundation', 'applied', 'AO2'),
  (4, 'Sources of finance', 'What is a business angel?', 'A government grant that is given to new and small businesses', 'A wealthy person who invests in return for a share of the business', 'A loyal customer who always pays the business on time', 'A bank that only lends money to businesses that are just starting up', 'B', 'Business angels and venture capitalists give finance and often advice, but the owners give up part of the business.', 'foundation', 'recall', 'AO1'),
  (5, 'Sources of finance', 'A public limited company needs £50 million to build a new factory and does not want to pay interest. Which source of finance is most suitable?', 'A bank overdraft', 'A loan from family and friends', 'Trade credit', 'A share issue', 'D', 'Selling new shares can raise large sums without interest, although the original owners'' control is diluted.', 'higher', 'applied', 'AO2'),
  (6, 'Sources of finance', 'What is a disadvantage of a bank loan as a source of finance?', 'Only charities are allowed to use it', 'It never has to be paid back', 'The owners lose control of the business', 'Interest has to be paid on it', 'D', 'Loans must be repaid with interest, which adds to costs. Selling shares, not a loan, dilutes ownership.', 'foundation', 'recall', 'AO1'),
  (7, 'Revenue, costs and profit', 'Which of these is a variable cost for a furniture maker?', 'The manager''s yearly salary', 'Insurance for the workshop building', 'Rent on the workshop it uses', 'Wood used to make the furniture', 'D', 'Variable costs change with output: more furniture needs more wood. Rent, insurance and salaries are fixed costs.', 'foundation', 'recall', 'AO1'),
  (8, 'Revenue, costs and profit', 'A business sells 500 units at £8 each. What is its total revenue?', '£400', '£40,000', '£4,000', '£508', 'C', 'Total revenue = selling price × quantity sold = 8 × 500 = £4,000.', 'foundation', 'calculation', 'AO2'),
  (9, 'Revenue, costs and profit', 'A business has fixed costs of £2,000 and variable costs of £3 per unit. What are its total costs if it makes 400 units?', '£1,200', '£3,200', '£2,400', '£5,200', 'B', 'Total costs = fixed costs + (variable cost per unit × output) = 2,000 + (3 × 400) = £3,200.', 'foundation', 'calculation', 'AO2'),
  (10, 'Revenue, costs and profit', 'A business sells 1,000 units at £5 each. Fixed costs are £1,500 and variable costs are £2 per unit. What is its profit?', '£1,000', '£3,000', '£3,500', '£1,500', 'D', 'Total revenue = £5,000. Total costs = 1,500 + 2,000 = £3,500. Profit = 5,000 − 3,500 = £1,500.', 'foundation', 'calculation', 'AO2'),
  (11, 'Revenue, costs and profit', 'What are fixed costs?', 'Costs that are only ever paid once', 'Costs that stay the same as output changes', 'Costs that the business never has to pay', 'Costs that rise with every extra unit produced', 'B', 'Fixed costs stay the same in the short term whatever the output. Variable costs change with output.', 'foundation', 'recall', 'AO1'),
  (12, 'Break-even', 'A product sells for £12 and has a variable cost of £7 per unit. What is the contribution per unit?', '£84', '£7', '£19', '£5', 'D', 'Contribution per unit = selling price − variable cost per unit = 12 − 7 = £5.', 'foundation', 'calculation', 'AO2'),
  (13, 'Break-even', 'A business has fixed costs of £6,000. It sells its product for £10, and the variable cost is £4 per unit. How many units must it sell to break even?', '1,000 units', '600 units', '1,500 units', '429 units', 'A', 'Break-even = fixed costs ÷ contribution per unit = 6,000 ÷ (10 − 4) = 1,000 units.', 'foundation', 'calculation', 'AO2'),
  (14, 'Break-even', 'On a break-even chart, where is the break-even point?', 'At the highest point of the total cost line', 'Where the total revenue line starts', 'Where the total revenue line crosses the total cost line', 'Where the fixed cost line crosses the variable cost line', 'C', 'At break-even, total revenue equals total costs, so the business makes neither a profit nor a loss.', 'foundation', 'recall', 'AO1'),
  (15, 'Break-even', 'The variable cost per unit of a product rises, but its selling price stays the same. What happens to the break-even output?', 'It falls to zero', 'It falls', 'It rises', 'It stays the same', 'C', 'Contribution per unit falls, so more units must be sold to cover the same fixed costs.', 'foundation', 'applied', 'AO3'),
  (16, 'Break-even', 'A business has fixed costs of £9,000 and variable costs of £9 per unit. It raises its selling price from £15 to £18. What is its new break-even output?', '1,000 units', '500 units', '1,500 units', '600 units', 'A', 'New contribution = 18 − 9 = £9. Break-even = 9,000 ÷ 9 = 1,000 units, down from 9,000 ÷ 6 = 1,500 at the old price.', 'higher', 'calculation', 'AO2'),
  (17, 'Average rate of return (ARR)', 'What does the average rate of return (ARR) measure?', 'The rate of interest a bank charges on a business loan', 'How many years it takes the business to repay a bank loan', 'Average yearly profit as a percentage of the initial cost', 'The total revenue an investment earns over its whole life', 'C', 'ARR is used to judge the success of an investment and to compare different investments.', 'foundation', 'recall', 'AO1'),
  (18, 'Average rate of return (ARR)', 'An investment costs £50,000 and makes a total net profit of £20,000 over 5 years. What is the ARR?', '8%', '40%', '4%', '25%', 'A', 'Average annual return = 20,000 ÷ 5 = £4,000. ARR = 4,000 ÷ 50,000 × 100 = 8%. 40% forgets to divide by the number of years.', 'foundation', 'calculation', 'AO2'),
  (19, 'Average rate of return (ARR)', 'A machine costs £80,000 and is expected to make a total net profit of £24,000 over 4 years. What is the ARR?', '3.3%', '30%', '7.5%', '6%', 'C', 'Average annual return = 24,000 ÷ 4 = £6,000. ARR = 6,000 ÷ 80,000 × 100 = 7.5%.', 'foundation', 'calculation', 'AO2'),
  (20, 'Average rate of return (ARR)', 'Project A costs £100,000 and makes a total net profit of £60,000 over 4 years. Project B costs £40,000 and makes a total net profit of £30,000 over 3 years. Which project has the higher ARR?', 'Project A, with an ARR of 60%', 'Project B, with an ARR of 75%', 'Project A, with an ARR of 15%', 'Project B, with an ARR of 25%', 'D', 'A: 60,000 ÷ 4 = 15,000; 15,000 ÷ 100,000 = 15%. B: 30,000 ÷ 3 = 10,000; 10,000 ÷ 40,000 = 25%. B has the higher ARR even though its total profit is lower.', 'higher', 'calculation', 'AO3'),
  (21, 'Profit and loss accounts (income statements) and profit margins', 'How is gross profit calculated?', 'Sales revenue − all expenses', 'Sales revenue × cost of sales', 'Net profit + cost of sales', 'Sales revenue − cost of sales', 'D', 'Gross profit = revenue − cost of sales. Net profit = gross profit − expenses.', 'foundation', 'recall', 'AO1'),
  (22, 'Profit and loss accounts (income statements) and profit margins', 'A business has sales revenue of £200,000, cost of sales of £120,000 and expenses of £50,000. What is its net profit?', '£30,000', '£150,000', '£70,000', '£80,000', 'A', 'Gross profit = 200,000 − 120,000 = £80,000. Net profit = 80,000 − 50,000 = £30,000. £80,000 is the gross profit.', 'higher', 'calculation', 'AO2'),
  (23, 'Profit and loss accounts (income statements) and profit margins', 'A business has gross profit of £40,000 on sales of £160,000. What is its gross profit margin?', '4%', '40%', '25%', '75%', 'C', 'GPM = gross profit ÷ sales × 100 = 40,000 ÷ 160,000 × 100 = 25%.', 'foundation', 'calculation', 'AO2'),
  (24, 'Profit and loss accounts (income statements) and profit margins', 'A business has sales of £250,000 and net profit of £20,000. What is its net profit margin?', '80%', '20%', '12.5%', '8%', 'D', 'NPM = net profit ÷ sales × 100 = 20,000 ÷ 250,000 × 100 = 8%.', 'foundation', 'calculation', 'AO2'),
  (25, 'Profit and loss accounts (income statements) and profit margins', 'A business''s gross profit margin stays at 40%, but its net profit margin falls from 15% to 9%. What is the most likely cause?', 'Its suppliers have raised the price of its materials', 'It has cut its selling prices', 'Its cost of sales has risen faster than its sales', 'Its expenses, such as rent or salaries, have risen', 'D', 'If GPM is unchanged, revenue and cost of sales are in the same proportion. The gap must come from higher expenses (overheads), which reduce net profit only.', 'higher', 'applied', 'AO3'),
  (26, 'Cash-flow', 'Why can a profitable business still run out of cash?', 'Cash is only needed by loss-making businesses', 'Customers may pay late while bills are due', 'Profitable businesses do not need any cash', 'Profit and cash are always exactly the same', 'B', 'Profit is revenue minus costs over a period; cash is the money actually in the bank. Selling on credit means revenue is earned before the cash arrives.', 'foundation', 'recall', 'AO1'),
  (27, 'Cash-flow', 'A business has an opening balance of £3,000. Its cash inflows are £10,000 and its cash outflows are £12,500. What is its closing balance?', '£5,500', '£500', '£25,500', '−£2,500', 'B', 'Net cash-flow = 10,000 − 12,500 = −£2,500. Closing balance = 3,000 − 2,500 = £500.', 'foundation', 'calculation', 'AO2'),
  (28, 'Cash-flow', 'In a cash-flow forecast, what is net cash-flow?', 'Total outflows plus total inflows', 'Total cash inflows minus total cash outflows', 'The money in the bank at the start of the month', 'Total revenue minus cost of sales', 'B', 'Net cash-flow is added to the opening balance to give the closing balance.', 'foundation', 'recall', 'AO1'),
  (29, 'Cash-flow', 'Which action would improve a business''s cash-flow?', 'Giving customers longer to pay', 'Buying extra stock in advance', 'Asking customers to pay sooner', 'Paying suppliers earlier than needed', 'C', 'Cash-flow improves if money comes in sooner or goes out later. Other options include delaying payments, cutting costs and extra funding.', 'foundation', 'applied', 'AO2'),
  (30, 'Cash-flow', 'In month 1 a business has an opening balance of £2,000 and a net cash-flow of −£3,000. In month 2 its net cash-flow is +£1,500. What is its closing balance at the end of month 2?', '£500', '−£1,000', '£3,500', '£6,500', 'A', 'Month 1 closing = 2,000 − 3,000 = −£1,000. This is month 2''s opening balance. Month 2 closing = −1,000 + 1,500 = £500.', 'higher', 'calculation', 'AO2'),
  (31, 'Cash-flow', 'In a cash-flow forecast, what is the opening balance for a month?', 'That month''s net cash-flow', 'That month''s total inflows', 'The previous month''s closing balance', 'The amount of profit made that month', 'C', 'Closing balance = opening balance + net cash-flow, and it becomes the next month''s opening balance.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Finance') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

