insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing'), 'Market research', 'B5.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing'), 'The marketing mix', 'B5.3', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing'), 'Product and the product life cycle', 'B5.4', 4);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing'), 'Price', 'B5.5', 5);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing'), 'Promotion', 'B5.6', 6);
