insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Identifying and understanding customers (segmentation)', 'A business divides its market by where customers live. What type of segmentation is this?', 'Income', 'Gender', 'Lifestyle', 'Geographic', 'D', 'The specification lists segmentation by age, gender, income, geographic area and lifestyle.', 'foundation', 'recall', 'AO1'),
  (2, 'Identifying and understanding customers (segmentation)', 'Why do businesses segment their market?', 'To target products at the right customers', 'To avoid having to carry out any market research', 'To sell exactly the same product to everyone', 'To stop new competitors from entering the market', 'A', 'Segmentation divides a mass market into groups, helping the business satisfy customer needs and increase sales and profit.', 'foundation', 'recall', 'AO1'),
  (3, 'Identifying and understanding customers (segmentation)', 'A gym offers cheap off-peak membership for people over 65. Which type of segmentation is it using?', 'Lifestyle', 'Gender', 'Geographic', 'Age', 'D', 'The offer is aimed at a particular age group, many of whom are retired and free during the day.', 'foundation', 'applied', 'AO2'),
  (4, 'Market research', 'Which of these is primary (field) research?', 'A survey the business carries out itself', 'Looking at competitors'' websites and prices', 'Reading articles in newspapers and magazines', 'Reading government population statistics', 'A', 'Primary research collects new data first-hand. The others use data that already exists, so they are secondary (desk) research.', 'foundation', 'recall', 'AO1'),
  (5, 'Market research', 'Which of these is secondary (desk) research?', 'Watching how shoppers move around a store', 'Holding a focus group with customers', 'Interviewing customers in the street', 'Using government population statistics', 'D', 'Secondary research uses existing data, from internal sources (such as sales records) or external sources (such as government data and the internet).', 'foundation', 'recall', 'AO1'),
  (6, 'Market research', 'What is the main advantage of secondary research compared with primary research?', 'It is usually cheaper and quicker to collect', 'It is collected specifically for the business''s own needs', 'It is always more up to date', 'Competitors cannot see it', 'A', 'Secondary data already exists, but it may be out of date or not exactly what the business needs.', 'foundation', 'recall', 'AO1'),
  (7, 'Market research', 'A business holds a focus group to discuss a new snack. What type of data will this mainly produce?', 'Quantitative data', 'Financial data', 'Qualitative data', 'Secondary data', 'C', 'A focus group gives opinions, feelings and reasons, which is qualitative data.', 'foundation', 'applied', 'AO2'),
  (8, 'Market research', 'A new café owner wants to find out how much local people would pay for a coffee, but has a very small budget. Which research method is most suitable?', 'Running a television advert asking for feedback', 'Buying a national market research report', 'A short survey of people in the local area', 'Using national census data', 'C', 'A local survey is cheap and gives first-hand answers about the café''s own target market. National data would not show what local people would pay.', 'higher', 'applied', 'AO3'),
  (9, 'Market research', 'Why might market research results be unreliable?', 'The sample may be too small or not represent the target market', 'The questions were about the business''s own product', 'The results were collected recently', 'The business has used both primary and secondary research', 'A', 'Research data must be accurate and up to date. Small or biased samples, and out-of-date data, limit its usefulness.', 'foundation', 'recall', 'AO1'),
  (10, 'The marketing mix', 'What are the four Ps of the marketing mix?', 'Promotion, profit, place and purchasing', 'Product, price, promotion and place', 'Product, profit, people and planning', 'Price, packaging, production and place', 'B', 'A business combines the four Ps to create a marketing strategy that meets customer needs.', 'foundation', 'recall', 'AO1'),
  (11, 'The marketing mix', 'A new competitor opens near a successful burger restaurant. How might the restaurant change its marketing mix in response?', 'Raise all of its prices sharply', 'Cut some prices and promote more', 'Close the restaurant at weekends', 'Stop all of its advertising to save money', 'B', 'The marketing mix has to adapt as market conditions change, such as when competition increases.', 'higher', 'applied', 'AO3'),
  (12, 'Product and the product life cycle', 'In which stage of the product life cycle do sales rise quickly?', 'Introduction', 'Decline', 'Growth', 'Maturity', 'C', 'In the growth stage more customers buy the product and sales rise rapidly. The stages are introduction, growth, maturity, saturation and decline.', 'foundation', 'recall', 'AO1'),
  (13, 'Product and the product life cycle', 'Which of these is an extension strategy?', 'Withdrawing the product from sale', 'Relaunching the product with new packaging', 'Launching the product for the first time', 'Cutting all advertising for the product', 'B', 'Extension strategies, such as new versions, packaging, markets or uses, try to stop sales falling in maturity or decline.', 'foundation', 'recall', 'AO1'),
  (14, 'Product and the product life cycle', 'In which stage of the product life cycle are sales low and promotion costs high, so the product often makes a loss?', 'Introduction', 'Growth', 'Saturation', 'Maturity', 'A', 'At launch, few customers know about the product, but the business spends heavily on promotion.', 'foundation', 'recall', 'AO1'),
  (15, 'Product and the product life cycle', 'What is a unique selling point (USP)?', 'The very first sale that a new business makes', 'The lowest price charged by any business in the market', 'A feature that makes a product different from rivals', 'The place or shop where a product is mainly sold', 'C', 'A USP gives customers a reason to choose the product over rivals. It is a form of product differentiation.', 'foundation', 'recall', 'AO1'),
  (16, 'Product and the product life cycle', 'What happens to sales in the saturation stage of the product life cycle?', 'They are zero because the product has not launched', 'They fall to nothing as the product is withdrawn', 'They level off because the market is full', 'They rise faster than at any other stage', 'C', 'In saturation the market is full and competition is intense, so sales level off before decline.', 'foundation', 'recall', 'AO1'),
  (17, 'Product and the product life cycle', 'Why does a business benefit from having a balanced product portfolio?', 'It removes the need for any promotion at all', 'Growing products offset those in decline', 'All its products are launched at the same time', 'It never needs to launch any new products', 'B', 'Having products at different life cycle stages spreads risk and keeps overall sales and cash-flow steadier.', 'higher', 'applied', 'AO3'),
  (18, 'Price', 'What is penetration pricing?', 'Charging £9.99 instead of a round £10', 'Adding a percentage to the cost of making it', 'A high price when a new product is launched', 'A low launch price to gain market share', 'D', 'Once the product has a loyal customer base, the price may be raised.', 'foundation', 'recall', 'AO1'),
  (19, 'Price', 'A company launches a new, high-tech games console at a very high price, then lowers the price later. Which pricing strategy is this?', 'Loss leader pricing', 'Penetration pricing', 'Price skimming', 'Cost-plus pricing', 'C', 'Skimming targets early adopters who will pay a high price for something new.', 'foundation', 'applied', 'AO2'),
  (20, 'Price', 'A product costs £4 to make. The business uses cost-plus pricing with a 25% mark-up. What is the selling price?', '£6.25', '£5.00', '£29.00', '£4.25', 'B', 'Mark-up = 25% of £4 = £1. Selling price = 4 + 1 = £5.00.', 'foundation', 'calculation', 'AO2'),
  (21, 'Price', 'A shop prices a jumper at £19.99 instead of £20. Which pricing strategy is this?', 'Price discrimination', 'Psychological pricing', 'Price skimming', 'Competitive pricing', 'B', 'Prices just below a round number seem much cheaper to customers.', 'foundation', 'recall', 'AO1'),
  (22, 'Price', 'What is a loss leader?', 'A product sold below cost to attract customers', 'The cheapest product that a rival business sells', 'A product that has made a loss for several years', 'A product that is in the decline stage of its life cycle', 'A', 'Supermarkets often do this with items such as milk, hoping customers will buy other, profitable products.', 'foundation', 'recall', 'AO1'),
  (23, 'Price', 'A train company charges more for tickets at peak times than off-peak for the same journey. Which pricing strategy is this?', 'Price discrimination', 'Penetration pricing', 'Cost-plus pricing', 'Psychological pricing', 'A', 'Price discrimination charges different prices to different groups of customers for the same product.', 'foundation', 'applied', 'AO2'),
  (24, 'Promotion', 'Which of these is a sales promotion?', 'An email sent to past customers', 'A television advert', 'Buy one, get one free', 'A newspaper article about the business', 'C', 'Sales promotions are short-term offers to boost sales, such as BOGOF, discounts and free samples.', 'foundation', 'recall', 'AO1'),
  (25, 'Promotion', 'What is direct marketing?', 'Advertising the business on national television', 'Selling products through a wholesaler and retailers', 'Sending promotions straight to individual customers', 'Offering price discounts to everyone in the shop', 'C', 'Direct marketing targets particular customers rather than the general public.', 'foundation', 'recall', 'AO1'),
  (26, 'Promotion', 'A self-employed local plumber has a small promotion budget. Which method is most appropriate?', 'An advert on national television', 'An advert shown in cinemas across the UK', 'A full-page advert in a national newspaper', 'Leaflets and a local directory listing', 'D', 'The plumber only serves a local area, so cheap local promotion reaches the right customers without wasting money.', 'foundation', 'applied', 'AO2'),
  (27, 'Promotion', 'Why are social media adverts often useful for small businesses?', 'They guarantee that the business''s sales will rise', 'They only reach people who never go online', 'They can target particular groups cheaply', 'They are always completely free to place', 'C', 'Technology has allowed businesses to target adverts by age, location and interests, often cheaply.', 'foundation', 'applied', 'AO2'),
  (28, 'Place', 'What is the role of a wholesaler in a distribution channel?', 'It buys in bulk and sells smaller amounts to retailers', 'It manufactures the products in its own factories', 'It advertises the products on national television', 'It sells products directly to consumers through its website', 'A', 'In the channel manufacturer → wholesaler → retailer → consumer, the wholesaler breaks bulk for retailers.', 'foundation', 'recall', 'AO1'),
  (29, 'Place', 'A manufacturer switches from selling through retailers to selling directly to consumers online. How might this affect the final price?', 'It will always double', 'It could be lower, because no retailer adds its own mark-up', 'It cannot change', 'It must be higher, because there are more businesses in the channel', 'B', 'Each intermediary adds a mark-up, so a shorter channel can mean a lower price for the consumer.', 'higher', 'applied', 'AO3'),
  (30, 'Place', 'What is multi-channel distribution?', 'Buying supplies from several different suppliers', 'Selling through several channels, such as shops and online', 'Advertising a product on several different TV channels', 'Selling a product through only one shop in one town', 'B', 'Multi-channel distribution gives customers choice and convenience, aiming to increase sales and loyalty.', 'foundation', 'recall', 'AO1'),
  (31, 'Place', 'How has the growth of e-commerce affected many physical shops?', 'High street shops have all doubled their sales', 'Shops no longer need to sell any products', 'Fewer shoppers, and some shops have closed', 'People have stopped shopping online completely', 'C', 'E-commerce and m-commerce let customers buy anywhere at any time, which has reduced footfall in many town centres.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

