update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Marketing');

insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Business'), 'Human Resources', 'B6', 'Components 1 and 2', 6);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Recruitment', 'B6.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Training', 'B6.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Motivation', 'B6.3', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Organisational structures and working practices', 'B6.4', 4);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Recruitment', 'What does a job description set out?', 'The duties and responsibilities of the job', 'The skills and qualities of the ideal candidate', 'The questions to ask at interview', 'The candidate''s work history', 'A', 'A job description describes the job. A person specification describes the person needed to do it.', 'foundation', 'recall', 'AO1'),
  (2, 'Recruitment', 'Which document describes the skills, qualifications and qualities the ideal candidate should have?', 'A person specification', 'A contract of employment', 'A curriculum vitae (CV)', 'A job description', 'A', 'Applicants are compared with the person specification when the business shortlists candidates.', 'foundation', 'recall', 'AO1'),
  (3, 'Recruitment', 'What is an advantage of internal recruitment?', 'It is usually quicker and cheaper', 'It gives a wider choice of candidates', 'It brings in new ideas from outside', 'It creates no other vacancy', 'A', 'Internal recruitment saves time and money, but it limits the choice of candidates and leaves another job to fill.', 'foundation', 'recall', 'AO1'),
  (4, 'Recruitment', 'In the recruitment process, what usually happens after applications have been received?', 'The applications are shortlisted', 'The job is advertised for the first time', 'A job description is written', 'The vacancy is identified', 'A', 'The process runs: identify vacancy, prepare job description and person specification, advertise, shortlist, check references, interview, then select and appoint.', 'foundation', 'recall', 'AO1'),
  (5, 'Recruitment', 'A call centre wants to see how applicants handle an angry customer. Which selection method is most suitable?', 'Reading their references', 'A maths aptitude test', 'A role play', 'Checking their CVs', 'C', 'Role play shows how candidates actually behave in a realistic situation from the job.', 'foundation', 'applied', 'AO2'),
  (6, 'Recruitment', 'A small business urgently needs a specialist IT manager, and none of its staff has the right skills. Which recruitment method is most appropriate?', 'Waiting until someone sends in a CV', 'External recruitment via a specialist agency', 'Internal recruitment by promoting an employee', 'Asking several existing staff to share the role', 'B', 'Internal recruitment cannot work if no one has the skills. A specialist agency can find suitable candidates quickly, although it charges a fee.', 'higher', 'applied', 'AO3'),
  (7, 'Training', 'What is induction training?', 'Training that introduces new staff to the business', 'Training that is given when an employee is leaving', 'Training that is given to managers and nobody else', 'Training staff to use a new piece of technology', 'A', 'Induction covers things like health and safety, the business''s rules and meeting colleagues.', 'foundation', 'recall', 'AO1'),
  (8, 'Training', 'Which of these is an example of on-the-job training?', 'A day-release college course', 'A sandwich course at university', 'Job shadowing an experienced colleague', 'A course run at a hotel by outside trainers', 'C', 'On-the-job training happens at work while doing the job: demonstration, coaching, mentoring, job shadowing and job rotation.', 'foundation', 'recall', 'AO1'),
  (9, 'Training', 'What is an advantage of off-the-job training?', 'Staff learn from specialist trainers without distractions', 'It costs the business nothing at all to provide', 'It always takes place at the employee''s own workstation', 'Employees carry on producing goods while they train', 'A', 'Off-the-job training can be high quality, but it costs more and employees are not working while they train.', 'foundation', 'recall', 'AO1'),
  (10, 'Training', 'Which of these is a benefit of effective training?', 'More mistakes made at work', 'Higher absence among staff', 'More customer complaints', 'Less wastage of materials', 'D', 'Training improves morale, quality and customer satisfaction, and can reduce wastage and costs.', 'foundation', 'recall', 'AO1'),
  (11, 'Motivation', 'What is piece rate?', 'Paying workers a fixed amount each year', 'Paying workers for each item they produce', 'Paying workers for each hour they work', 'Paying workers a share of the profits', 'B', 'Time rate pays per hour, salaries are fixed yearly amounts and profit sharing pays a share of profits.', 'foundation', 'recall', 'AO1'),
  (12, 'Motivation', 'What is commission?', 'Extra pay for working more than normal hours', 'A company car given to senior staff', 'Pay based on the value of sales made', 'A fixed wage paid at the end of each week', 'C', 'Commission is a type of performance-related pay, common for sales staff.', 'foundation', 'recall', 'AO1'),
  (13, 'Motivation', 'What is job enrichment?', 'Giving staff more tasks at the same level', 'Paying staff a bonus for meeting targets', 'Moving staff between different tasks', 'Giving staff more responsibility', 'D', 'Job enlargement adds more tasks of the same level; job rotation moves workers between tasks. Enrichment adds responsibility and challenge.', 'higher', 'recall', 'AO1'),
  (14, 'Motivation', 'Workers on a production line swap between different tasks every few weeks. What is this called?', 'Profit sharing', 'Empowerment', 'Job enrichment', 'Job rotation', 'D', 'Job rotation gives variety and helps workers learn new skills.', 'foundation', 'applied', 'AO2'),
  (15, 'Motivation', 'Which of these is a benefit to a business of a motivated workforce?', 'Lower staff turnover', 'Higher absenteeism', 'Worse relations between workers and managers', 'More customer complaints', 'A', 'Motivated workers are more likely to stay, attend work and perform well.', 'foundation', 'recall', 'AO1'),
  (16, 'Motivation', 'A factory pays its workers piece rate and finds that the quality of its products is falling. What is the most likely reason?', 'Workers have been given too much responsibility', 'Workers rush because pay depends on quantity', 'Workers are paid the same however much they make', 'Workers are paid a share of the business''s profits', 'B', 'Piece rate rewards quantity, not quality, so the business may need quality checks or a different pay method.', 'higher', 'applied', 'AO3'),
  (17, 'Organisational structures and working practices', 'What is meant by span of control?', 'The number of staff a manager directly supervises', 'The total number of employees in a business', 'The amount of money a manager is allowed to spend', 'The number of levels in a business''s hierarchy', 'A', 'A wide span means a manager has many subordinates; a narrow span means few.', 'foundation', 'recall', 'AO1'),
  (18, 'Organisational structures and working practices', 'Compared with a tall structure, a flat structure has…', 'no managers at all', 'fewer layers of management and wider spans of control', 'a longer chain of command', 'more layers of management and narrower spans of control', 'B', 'Flat structures usually communicate faster, but each manager has more people to supervise.', 'foundation', 'recall', 'AO1'),
  (19, 'Organisational structures and working practices', 'What is delayering?', 'Moving the business to a new location', 'Recruiting more operatives to the business', 'Removing layers of management', 'Adding extra layers of management', 'C', 'Delayering is one way to solve problems of tall structures, such as slow communication.', 'foundation', 'recall', 'AO1'),
  (20, 'Organisational structures and working practices', 'What is the chain of command?', 'The line of authority from the top down', 'The number of staff one manager supervises', 'The order in which products are made', 'The route goods take to reach customers', 'A', 'Instructions pass down the chain of command; tall structures have longer chains.', 'foundation', 'recall', 'AO1'),
  (21, 'Organisational structures and working practices', 'What is a zero hours contract?', 'A contract with no guaranteed hours of work', 'A contract that is only for working from home', 'A contract where two people share one job', 'A contract for full-time work with fixed hours', 'A', 'Zero hours contracts give businesses flexibility, but workers have no guaranteed income.', 'foundation', 'recall', 'AO1'),
  (22, 'Organisational structures and working practices', 'What is the main role of a trade union?', 'To recruit new managers on behalf of businesses', 'To collect taxes from businesses for the government', 'To set the prices that businesses charge for products', 'To negotiate better pay and conditions for workers', 'D', 'Trade unions represent workers and may take industrial action, such as go-slows or strikes.', 'foundation', 'recall', 'AO1'),
  (23, 'Organisational structures and working practices', 'A business removes a layer of middle managers. What is the most likely effect?', 'A longer chain of command from top to bottom', 'Slower communication and narrower spans of control', 'Faster communication, but wider spans of control', 'More promotion opportunities for staff', 'C', 'Delayering shortens the chain of command, but each remaining manager supervises more people and there are fewer promotion opportunities.', 'higher', 'applied', 'AO3'),
  (24, 'Organisational structures and working practices', 'In a business, a managing director has 3 directors reporting to them. Each director has 4 managers, and each manager has 6 operatives. How many levels of hierarchy are there, and what is each manager''s span of control?', '4 levels; a span of control of 4', '13 levels; a span of control of 6', '4 levels; a span of control of 6', '3 levels; a span of control of 4', 'C', 'The levels are managing director, directors, managers and operatives (4). Each manager directly supervises 6 operatives.', 'higher', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Quiz 1', 1, 0, 168);
insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources'), 'Quiz 2', 2, 0, 168);
with ordered as (
  select q.id, row_number() over (order by q.created_at) - 1 as i
  from questions q join subtopics s on s.id = q.subtopic_id
  where q.generation_batch_id = '3845bb7b-2410-4a62-b8d7-cc41a4035446'::uuid and q.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources')
)
insert into quiz_questions (quiz_id, question_id, position)
select z.id, o.id, (o.i / 2)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources') and z.title = 'Quiz ' || ((o.i % 2) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Business') and name = 'Human Resources');

